const FFL_FULL_LICENSE_PLAIN_REGEX = /^[A-Za-z0-9]{15}$/;
const FFL_SHORT_LICENSE_REGEX = /^\d{8}$/;
const FFL_SHORT_LICENSE_DASHED_REGEX = /^\d-\d{2}-\d{5}$/;
