  const toShortLicense = (licenseInput: string): string => {
    const alnumOnly = licenseInput.replace(/[^A-Za-z0-9]/g, "").toUpperCase();

    if (FFL_SHORT_LICENSE_REGEX.test(alnumOnly)) {
      return alnumOnly;
    }

    return `${alnumOnly.slice(0, 3)}${alnumOnly.slice(-5)}`;
  };

  const sanitizeFflLicenseInput = (raw: string): string => {
    let alnumCount = 0;
    let next = "";

    for (const char of raw.toUpperCase()) {
      if (/[A-Z0-9]/.test(char)) {
        if (alnumCount >= 15) continue;
        next += char;
        alnumCount += 1;
        continue;
      }

      if (char === "-") {
        next += char;
      }
    }

    return next;
  };

