
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import { SDK } from "../../sdk";
import { CheckoutStepType, type CheckoutContextProps, type MasterFFLContextType } from "../../types";
export { MasterFFLShippingUI } from "./components/MasterFFLShippingUI";
const MasterFFLContext = createContext<MasterFFLContextType | undefined>(undefined);

export const useMasterFFL = (): MasterFFLContextType => {
  const context = useContext(MasterFFLContext);

  if (context === undefined) {
    throw new Error("useMasterFFL must be used within a MasterFFLProvider");
  }

  return context;
};

export const MasterFFLProvider = ({
  checkoutContext,
  getCheckoutStepStatuses,
  goToStep,
  children,
}: {
  checkoutContext: any;
  getCheckoutStepStatuses: any;
  goToStep?: (step: any, options?: any) => void;
  children: ReactNode;
}) => {
  type HardBlockReason =
    | "none"
    | "restricted_state"
    | "product_state_rule";

  type CheckoutRestrictionResult = {
    state: string | null;
    directToDealerRequired: boolean;
    directToDealerRestrictedKeys: string[];
    hardBlocked: boolean;
    hardBlockReason: HardBlockReason;
    blockedProductIds: number[];
    hardBlockMessage: string;
  };

  const [lastCheckedZip, setLastCheckedZip] = useState<string | null>(null);
  const [initReady, setInitReady] = useState(false);
  const [shippingLocked, setShippingLocked] = useState(true);
  const mutationTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const consignmentObserverRef = useRef<MutationObserver | null>(null);
  const isMarkingConsignmentRef = useRef(false);

  // CHANGED FOR COMPATIBILITY WITH NEW CHECKOUT-JS
  //const { checkoutService, checkoutState } = useContext(checkoutContext) as CheckoutContextProps;
  const { checkoutService, checkoutState } = checkoutContext as CheckoutContextProps;
  const storeProfile = useMemo(() => checkoutState.data.getConfig()?.storeProfile, [checkoutState]);
  const checkoutId = useMemo(() => checkoutState.data.getCheckout()?.id, [checkoutState]);
  const storeHash = useMemo(() => storeProfile?.storeHash, [storeProfile]);


  const [isModalOpen, setIsModalOpen] = useState(false);
  const [values, setValues] = useState({
    postalCode: "",
    acceptTerms: true,
  });
  const [error, setError] = useState<string | null>(null);
  const [selectedDealer, setSelectedDealer] = useState<any>(null);
  const [isFFL, setIsFFL] = useState(false);
  const [fflLineItems, setFflLineItems] = useState<Map<number, any>>(new Map());
  const [isSuppressor, setIsSuppressor] = useState(false);
  const [isEntirelyFFL, setIsEntirelyFFL] = useState(false);
  const [hasFederalFFLItems, setHasFederalFFLItems] = useState(false);
  const [potentialRestrictedProducts, setPotentialRestrictedProducts] = useState(new Map<number, string>());
  const [isStateRestrictedOnly, setIsStateRestrictedOnly] = useState(false);
  const [restrictedTypesInCart, setRestrictedTypesInCart] = useState<string[]>([]);
  const [checkout, setCheckout] = useState<any>(null);
  const [isFFLB2BFlowEnabled, setIsFFLB2BFlowEnabled] = useState(false);

  const config = useMemo(
    () => ({
      ...SDK.getConfig(),
      storeHash,
      checkoutId: checkoutState.data.getCheckout()?.id,
    }),
    [storeHash, checkoutState]
  );

  useEffect(() => {
    window.masterFFLConfig = {
      ...(window.masterFFLConfig || {}),
      storeHash,
      checkoutId: checkoutState.data.getCheckout()?.id,
    } as any;
  }, [storeHash, checkoutState]);

  useEffect(() => {
    (window as any).masterFFLConditional = {
      ...(window as any).masterFFLConditional,
      fflB2BFlowEnabled: isFFLB2BFlowEnabled,
    };
  }, [isFFLB2BFlowEnabled]);

  useEffect(() => {
    const existingFlag = (window as any).masterFFLConditional?.fflB2BFlowEnabled;
    if (typeof existingFlag === "boolean") {
      setIsFFLB2BFlowEnabled(existingFlag);
    }
  }, []);

  useEffect(() => {
    const removeFFLFormFields = () => {
      document.querySelectorAll<HTMLDivElement>('.form-field').forEach((field) => {
        
        if (field.closest('#MasterFFL-form')) return;

        const label = field.querySelector('label');
        if (!label) return;

        const textInput = field.querySelector<HTMLInputElement>('input[type="text"]');
        if (!textInput) return;

        const BLOCKED_LABEL_TERMS = ['ffl', 'cfd', 'ein'];
        const text = label.textContent?.toLowerCase() || '';
        const isB2bField = text.includes('ffl-isb2b');

        if (BLOCKED_LABEL_TERMS.some(term => text.includes(term))) {
          if (isB2bField) {
            field.style.display = 'none';
            field.setAttribute('data-masterffl-is-b2b-field', 'true');
            return;
          }

          field.remove();
        }
      });
    };

    removeFFLFormFields();

    const observer = new MutationObserver(removeFFLFormFields);

    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });

    return () => observer.disconnect();
  }, []);


  (async () => {
      const conditional = (window as any).masterFFLConditional;
      if (
        !conditional?.uiText ||
        !conditional?.uiText2 ||
        !conditional?.chooseDealerButtonTextColor ||
        !conditional?.chooseDealerButtonBgColor
      ) {
        const fetchUIText = await fetch(
          `${config.appUrl}/api/getStates?storeHash=${encodeURIComponent(storeHash!)}`,
          { method: "GET", headers: { "ngrok-skip-browser-warning": "true" } }
        );
        if (!fetchUIText.ok) return false;

        const { settings } = await fetchUIText.json();
       
        (window as any).masterFFLConditional = {
          ...(window as any).masterFFLConditional,
          uiText: settings?.["state-restrictions-ui"],
          uiText2: settings?.["state-restrictions-ui-after"],
          termsText: settings?.["terms-text"],
          mainFFLNoticeText: settings?.["heading-text"],
          buttonText: settings?.["dealer-label"],
          chooseDealerButtonTextColor: settings?.["choose-dealer-text-color"],
          chooseDealerButtonBgColor: settings?.["choose-dealer-button-bg-color"],
          fflB2BFlowEnabled: settings?.["ffl-b2b-flow"] === "Enable",
        };
        setIsFFLB2BFlowEnabled(settings?.["ffl-b2b-flow"] === "Enable");
      }
  })();


  const markFFLConsignment = useCallback(async () => {
      // Prevent re-entrant calls
      if (isMarkingConsignmentRef.current) return;
      isMarkingConsignmentRef.current = true;
  
      try {
        // Find all consignment containers first
        const containers = document.querySelectorAll(".consignment-container");
        if (containers.length === 0) {
          isMarkingConsignmentRef.current = false;
          return;
        }
  
        const consignments = checkout?.consignments || checkout?.data?.consignments || [];
  
        // Find the FFL consignment from API data
        let fflConsignment = null;
        let fflConsignmentId = null;
  
        // Match by selected dealer address if available (most reliable)
        if (selectedDealer) {
          const dealerZip = selectedDealer?.contact?.address?.zip;
          const dealerStreet1 = selectedDealer?.contact?.address?.street1;
          const dealerCity = selectedDealer?.contact?.address?.city;
          const dealerState = selectedDealer?.contact?.address?.state;
  
          for (const consignment of consignments) {
            const address = consignment?.address;
            if (address) {
              // Match by postal code and street address
              const zipMatch = address.postalCode === dealerZip;
              const streetMatch = address.address1 === dealerStreet1;
              const cityMatch = address.city === dealerCity;
              const stateMatch = address.stateOrProvinceCode === dealerState;
  
              // If we have multiple matches, it's likely the FFL consignment
              if ((zipMatch && streetMatch) || (zipMatch && cityMatch && stateMatch)) {
                fflConsignment = consignment;
                fflConsignmentId = consignment.id;
                break;
              }
            }
          }
        }
  
        // If we still don't have a match, try matching by product IDs (check if consignment has FFL products)
        for (const consignment of consignments) {
          const lineItems = consignment?.lineItemIds || [];
          if (lineItems.length === 0) continue;
  
          // Check if any product in this consignment is an FFL product
          const hasFFLItems = lineItems.some((itemId: any) => SDK.fflLineItems.has(itemId));
  
          if (hasFFLItems) {
            fflConsignment = consignment;
            fflConsignmentId = consignment.id;
            break;
          }
        }
  
        if (!fflConsignment) {
          isMarkingConsignmentRef.current = false;
          return;
        }
  
        // Remove the class from all containers first
        containers.forEach((container) => {
          container.classList.remove("consignment-container--ffl");
        });
  
        const handleHideAddressToggle = (consignment: any) => {
          const addressToggle = consignment.querySelector("#addressToggle") as HTMLLinkElement;
          if (addressToggle) {
            const parent = addressToggle.parentElement;
            if (parent) {
              parent.style.display = "none";
  
              consignment.querySelector(".consignment-header h3").textContent = "FFL Destination";
            }
          }
        };
  
        // Try to find the matching DOM container
        // Method 1: Check for consignment ID in data attributes
        if (fflConsignmentId) {
          for (let i = 0; i < containers.length; i++) {
            const container = containers[i];
  
            // Check if container has data-consignment-id or similar attribute
            const containerId =
              container.getAttribute("data-consignment-id") ||
              container.getAttribute("data-id") ||
              container.querySelector("[data-consignment-id]")?.getAttribute("data-consignment-id");
  
            if (containerId && containerId === String(fflConsignmentId)) {
              container.classList.add("consignment-container--ffl");
              container.setAttribute("data-index", String(i));
              isMarkingConsignmentRef.current = false;
              handleHideAddressToggle(container);
              return;
            }
          }
        }
  
        // Method 2: Match by address text content
        const fflAddress = fflConsignment.address;
        if (fflAddress) {
          for (let i = 0; i < containers.length; i++) {
            const container = containers[i];
  
            const addressText = container.textContent || "";
  
            // Match by postal code and street address
            const postalCodeMatch = fflAddress.postalCode && addressText.includes(fflAddress.postalCode);
            const streetMatch = fflAddress.address1 && addressText.includes(fflAddress.address1);
            const cityMatch = fflAddress.city && addressText.includes(fflAddress.city);
            const stateMatch = fflAddress.stateOrProvinceCode && addressText.includes(fflAddress.stateOrProvinceCode);
  
            // Require at least postal code and one other match
            if (postalCodeMatch && (streetMatch || (cityMatch && stateMatch))) {
              container.classList.add("consignment-container--ffl");
              container.setAttribute("data-index", String(i));
              isMarkingConsignmentRef.current = false;
              handleHideAddressToggle(container);
              continue;
            }
          }
        }
      } finally {
        isMarkingConsignmentRef.current = false;
      }
    }, [selectedDealer, checkout]);

    const stopConsignmentSideEffects = useCallback(() => {
        if (mutationTimeoutRef.current) {
          clearTimeout(mutationTimeoutRef.current);
          mutationTimeoutRef.current = null;
        }

        if (consignmentObserverRef.current) {
          consignmentObserverRef.current.disconnect();
          consignmentObserverRef.current = null;
        }
    }, []);

    // Watch for consignment containers appearing
    const handleMutations = () => {
      // Debounce the mutation handler to prevent excessive calls
      if (isMarkingConsignmentRef.current) return;
      if (mutationTimeoutRef.current) clearTimeout(mutationTimeoutRef.current);
      mutationTimeoutRef.current = setTimeout(() => {
        markFFLConsignment();
        mutationTimeoutRef.current = null;
      }, 300);
    };

    consignmentObserverRef.current = new MutationObserver(handleMutations);
    consignmentObserverRef.current.observe(document.body, {
      childList: true,
      subtree: true,
    });

  function setFormControlValue(element: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement, value: string) {
    const tagName = element.tagName;

    if (tagName === "INPUT") {
      const input = element as HTMLInputElement;
      if (input.type === "checkbox" || input.type === "radio") {
        const checkedSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "checked")?.set;
        const boolValue = value === "true" || value === "on" || value === "1";
        checkedSetter ? checkedSetter.call(input, boolValue) : (input.checked = boolValue);
      } else {
        const valueSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
        valueSetter ? valueSetter.call(input, value) : (input.value = value);
      }
    } else if (tagName === "TEXTAREA") {
      const textarea = element as HTMLTextAreaElement;
      const valueSetter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;
      valueSetter ? valueSetter.call(textarea, value) : (textarea.value = value);
    } else if (tagName === "SELECT") {
      const select = element as HTMLSelectElement;
      const valueSetter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value")?.set;
      valueSetter ? valueSetter.call(select, value) : (select.value = value);
    }

    // Fire events so any React listeners update state
    element.dispatchEvent(new Event("input", { bubbles: true }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
  }

  const runZipRestrictionCheck = async (
    zip: string,
    isDealerCallback: boolean = false
  ): Promise<boolean> => {
    const emptyRestrictionResult: CheckoutRestrictionResult = {
      state: null,
      directToDealerRequired: false,
      directToDealerRestrictedKeys: [],
      hardBlocked: false,
      hardBlockReason: "none",
      blockedProductIds: [],
      hardBlockMessage: "",
    };

    try {
      setError(null);
      (window as any).masterFFLCheckoutRestrictionResult = emptyRestrictionResult;
      const zipRes = await fetch(`${config.appUrl}/api/getStateByZip?zip=${zip}`, {
        method: "GET",
        headers: { "ngrok-skip-browser-warning": "true" },
      });
      if (!zipRes.ok) return false;

      const { state } = await zipRes.json();
      if (!state) return false;

      (window as any).masterFFLConditional = {
        ...(window as any).masterFFLConditional,
        state,
      };

      const nextClassification = await SDK.init();
      const ruleEvaluation = (window as any).masterFFLRuleEvaluation || {};

      const statesRes = await fetch(
        `${config.appUrl}/api/getStates?storeHash=${encodeURIComponent(storeHash!)}`,
        { method: "GET", headers: { "ngrok-skip-browser-warning": "true" } }
      );
      const settings = statesRes.ok ? (await statesRes.json())?.settings : {};

      const restrictedKeys = Array.isArray(ruleEvaluation?.directToDealerRestrictedKeys)
        ? ruleEvaluation.directToDealerRestrictedKeys
        : [];

      const restrictionResult: CheckoutRestrictionResult = {
        state,
        directToDealerRequired: Boolean(ruleEvaluation?.directToDealerRequired),
        directToDealerRestrictedKeys: restrictedKeys,
        hardBlocked: Boolean(ruleEvaluation?.hardBlocked),
        hardBlockReason: ruleEvaluation?.matchedBlockAllRuleId
          ? "restricted_state"
          : Array.isArray(ruleEvaluation?.blockedProductIds) && ruleEvaluation.blockedProductIds.length > 0
            ? "product_state_rule"
            : "none",
        blockedProductIds: Array.isArray(ruleEvaluation?.blockedProductIds)
          ? ruleEvaluation.blockedProductIds
          : [],
        hardBlockMessage: String(ruleEvaluation?.hardBlockMessage || ""),
      };

      console.log("[MasterFFL][Rules] ZIP restriction result", {
        zip,
        state,
        nextClassification,
        ruleEvaluation,
        restrictionResult,
      });

      (window as any).masterFFLCheckoutRestrictionResult = restrictionResult;
        
      // SET THIS ONCE, AS THE SOURCE OF TRUTH, BEFORE ANY init call
      const stateRestrictedUi =
        typeof settings?.["state-restrictions-ui"] === "string"
          ? settings["state-restrictions-ui"]
          : "";
      const stateRestrictedUiAfter =
        typeof settings?.["state-restrictions-ui-after"] === "string"
          ? settings["state-restrictions-ui-after"]
          : "";

      (window as any).masterFFLConditional = {
        ...(window as any).masterFFLConditional,
        state,
        restrictedKeys, // <-- NOT []
        uiText: stateRestrictedUi,
        uiText2: stateRestrictedUiAfter,
        chooseDealerButtonTextColor: settings?.["choose-dealer-text-color"],
        chooseDealerButtonBgColor: settings?.["choose-dealer-button-bg-color"],
        fflB2BFlowEnabled: settings?.["ffl-b2b-flow"] === "Enable",
      };
      setIsFFLB2BFlowEnabled(settings?.["ffl-b2b-flow"] === "Enable");

      if (restrictionResult.hardBlocked) {
        const hardBlockMessage =
          restrictionResult.hardBlockMessage ||
          "Sorry, we cannot ship items in your cart to your state due to local regulations.";

        console.warn("[MasterFFL][StateBlock] Hard block triggered", restrictionResult);
        setError(hardBlockMessage);
        setShippingLocked(true);
        window.dispatchEvent(
          new CustomEvent("masterffl:hard-block", {
            detail: {
              title: "Shipping Restricted",
              message: hardBlockMessage,
              state,
              reason: restrictionResult.hardBlockReason,
              blockedProductIds: restrictionResult.blockedProductIds,
            },
          })
        );
        return false;
      }

      sessionStorage.setItem('masterFFL_fflZip', zip);
     
      setLastCheckedZip(zip);
      setShippingLocked(false);
     
      // Only re-init when dealer flow needs immediate reclassification
      if (isDealerCallback) {
        return !!nextClassification?.isFFL;
      } else if (restrictedKeys.length > 0) {
        handleInit(zip);
      }

      return true;
    } catch (err) {
      console.error("MasterFFL ZIP restriction check failed", err);
      (window as any).masterFFLCheckoutRestrictionResult = emptyRestrictionResult;
      return false;
    }
  };

  useEffect(() => {
    const checkOrigin = async () => {
      const referrer = document.referrer;

      const match = referrer.match(/^https?:\/\/[^/]+\/([^/?#]+)/);

      const firstPathSegment = match?.[1]; 

      if (firstPathSegment !== 'checkout') {
        const selectors = await checkoutService.loadCheckout(config.checkoutId, {
          params: { include: { "consignments.availableShippingOptions": true } },
        });

        let consignments = selectors.data.getConsignments?.() || [];

        if (consignments.length > 0) {
          consignments.forEach(cons => checkoutService.deleteConsignment(cons.id));
          sessionStorage.setItem('allowIgnoreZipGate', 'false');
          window.location.reload();
        }
      }
    }

    checkOrigin();

    const fflZip = sessionStorage.getItem("masterFFL_fflZip") || null;

    if (fflZip) {
      const handleClick = (event: Event) => {
      const target = event.target as HTMLElement | null;
      if (!target) return;
      
      const trigger = target.closest('[data-test="enter-shipping-address"]');
      if (!trigger) return;

      // Defer until modal DOM is mounted
      requestAnimationFrame(() => {
        waitForAddressFieldsAndForce(fflZip);
      });
    };

    document.addEventListener('click', handleClick);

    return () => {
      document.removeEventListener('click', handleClick);
    };
    }
  }, []);

  const waitForAddressFieldsAndForce = (fflZip: string) => {
    let attempts = 0;
    const MAX_ATTEMPTS = 20; 

    const interval = setInterval(() => {
      attempts++;

      const didApply = forceUSCountryAndZip(fflZip);

      if (didApply || attempts >= MAX_ATTEMPTS) {
        clearInterval(interval);
      }
    }, 50);
  };

  const forceUSCountryAndZip = (fflZip: string) => {
      let didApply = false;
  
      // =========================
      // COUNTRY
      // =========================
      const countrySelect = document.querySelector(
        'select[data-test="countryCodeInput-select"]'
      ) as HTMLSelectElement | null;
  
      if (countrySelect) {
        if (countrySelect.value !== 'US') {
          countrySelect.value = 'US';
          countrySelect.dispatchEvent(new Event('change', { bubbles: true }));
        }
  
        countrySelect.disabled = true;
        didApply = true;
      }
  
      // =========================
      // ZIP / POSTAL CODE
      // =========================
  
      const forceReactInputValue = (input: HTMLInputElement, value: string) => {
        const setter = Object.getOwnPropertyDescriptor(
          HTMLInputElement.prototype,
          'value'
        )?.set;
  
        setter?.call(input, value);
  
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
  
        // THIS is the missing piece
        input.blur();
      };
  
      const postalInput = document.querySelector(
        '.modalOverlay.modalOverlay--afterOpen input[data-test="postCodeInput-text"]'
      ) as HTMLInputElement | null;
     
      if (postalInput && fflZip) {
        
        if (postalInput.value !== fflZip) {
          forceReactInputValue(postalInput, fflZip);
        }
  
        postalInput.disabled = true;
        didApply = true;
      }
  
      return didApply;
    };

  useEffect(() => {
    // populate the values from the session storage on page load
    if (!checkoutId) return;

    const { postalCode, acceptTerms, selectedDealer } = SDK.getSession(checkoutId);

    if (postalCode) setValues((p) => ({ ...p, postalCode: postalCode }));
    if (acceptTerms) setValues((p) => ({ ...p, acceptTerms: acceptTerms }));
    if (selectedDealer && selectedDealer !== "null") setSelectedDealer(JSON.parse(selectedDealer));
  }, [checkoutId]);

  // config was here

  const handleSaveDealer = useCallback(
    async (dealer: any) => {
      // reset the selected dealer and error
      setSelectedDealer(null);
      setError(null);

      try {
        await SDK.saveDealer(checkoutId, dealer, undefined);
        setLastCheckedZip(dealer.address.zipCode);
        // set the selected dealer and save to session storage
        setSelectedDealer(dealer);
      } catch (error) {
        setError("An error occurred while saving the dealer. Please try again.");
      }
    },
    [checkoutId, checkoutService]
  );

  const steps = useMemo(
    () => getCheckoutStepStatuses(checkoutState),
    [checkoutState, getCheckoutStepStatuses]
  );

  const activeStep = useMemo(
    () => steps.find((s: any) => s.isActive),
    [steps]
  );

  const activeStepType = activeStep?.type;

  const forcedShippingRef = useRef(false);
  const hasInitializedRef = useRef(false);

  // FORCE SHIPPING STEP IF FFL item + no dealer + not on Shipping
  useEffect(() => {
    // If the host didn't pass navigation, we can't force anything.
    if (!goToStep) return;

    // Don't enforce until your init has run and state is accurate
    if (!initReady) return;

    const activeType = activeStep?.type;

    // Prevent skipping Customer step before email is captured
    const customerEmail =
      checkoutState.data.getCustomer?.()?.email ||
      checkoutState.data.getCheckout?.()?.customer?.email;

    const isOnCustomer = activeType === CheckoutStepType.Customer;
    if (isOnCustomer && !customerEmail) {
      forcedShippingRef.current = false; 
      return;
    }

    const isOnShipping = activeType === CheckoutStepType.Shipping;
    const sessionSelectedDealer = SDK.getSession(checkoutId)?.selectedDealer;
    const hasSelectedDealer =
      !!selectedDealer ||
      (!!sessionSelectedDealer && sessionSelectedDealer !== "null" && sessionSelectedDealer !== "{}");

    const mustForce =
      isFFL &&
      !hasSelectedDealer &&
      !isOnShipping;

    // Reset the guard when the condition is no longer true
    if (!mustForce) {
      forcedShippingRef.current = false;
      return;
    }

    if (forcedShippingRef.current) return;

    forcedShippingRef.current = true;

    console.warn("[MasterFFL][Enforce] FFL item + no dealer + not on Shipping → forcing Shipping");

    goToStep(CheckoutStepType.Shipping);
  }, [
    goToStep,
    initReady,
    isFFL,
    selectedDealer,
    checkoutId,
    activeStep?.type,
  ]);

  const handleCleanup = useCallback(async () => {
    
    if (!checkoutId) return;
    const previousDealer = sessionStorage.getItem(`${checkoutId}-selectedDealer`);
    const addressFields = document.querySelectorAll('[name^="shippingAddress."]');

    if (previousDealer) {
      SDK.removeSession(checkoutId, "postalCode");
      SDK.removeSession(checkoutId, "acceptTerms");
      SDK.removeSession(checkoutId, "selectedDealer");

      // clear the address fields
      
      addressFields.forEach((input) => {
        // Check the type of each Element before casting and using setFormControlValue
        if (input instanceof HTMLInputElement || input instanceof HTMLTextAreaElement || input instanceof HTMLSelectElement) {
          const nextValue = String("");
          setFormControlValue(input, nextValue);
        }
      });
    } else {
      addressFields.forEach((input) => {
        // Check the type of each Element before casting and using setFormControlValue
        if (input instanceof HTMLInputElement || input instanceof HTMLTextAreaElement || input instanceof HTMLSelectElement) {
          const name = input.getAttribute("name") || "";
          let nextValue = "";
          
          if (name === "shippingAddress.countryCode") nextValue = "US";

          setFormControlValue(input, nextValue);
        }
      });
      }
  }, [checkoutId]);

  const handleFixInvalidConsignments = useCallback(async (checkout: any) => {
    try {
      if (!checkout || !checkoutId) return;

      // Find duplicate consignments by shipping address (address1 and postalCode)
      const addressKey = (c: any) => `${c.shippingAddress?.address1 || ""}::${c.shippingAddress?.postalCode || ""}`;
      const consignmentMap = new Map<string, any[]>();
      for (const consignment of checkout.consignments || []) {
        if (!consignment.shippingAddress) continue;
        const key = addressKey(consignment);
        if (!consignmentMap.has(key)) {
          consignmentMap.set(key, []);
        }
        consignmentMap.get(key)!.push(consignment);
      }
      // Keep only arrays with more than one consignment (real duplicates)
      const hasDuplicateConsignments = Array.from(consignmentMap.values()).filter((arr) => arr.length > 1).flat();

      const consignments = checkout.consignments || [];
      if (consignments.length === 0) {
        return;
      }

      for (const consignment of consignments) {
        const lineItemIds = consignment.lineItemIds || [];

        if (lineItemIds.length === 0) {
          continue;
        }

        // if any of the items are FFL/NFA and are not attached to the dealer delete the consignment
        const hasFFLItems = lineItemIds.some((itemId: number) => {
          const item = checkout.cart.lineItems.physicalItems.find(
            (item: any) => item.id === itemId
          );

          if (!item) return false;

          const productId = Number(item.productId);

          return (
            SDK.fflProducts.has(productId) ||
            SDK.conditionalFFLProducts.has(productId)
          );
        });

        // const hasNonFFLItems = lineItemIds.some((itemId: number) => {
        //   const item = checkout.cart.lineItems.physicalItems.find(
        //     (item: any) => item.id === itemId
        //   );

        //   if (!item) return false;

        //   const productId = Number(item.productId);

        //   const isFFL =
        //     SDK.fflProducts.has(productId) ||
        //     SDK.conditionalFFLProducts.has(productId);

        //   return !isFFL;
        // });

        //const hasNonFFLItems = sessionStorage.getItem('hasNonFFLItems') === 'true';

        const dealer = JSON.parse(SDK.getSession(checkoutId)?.selectedDealer || "{}");

        const normalize = (v: any) =>
              String(v ?? "").trim().toUpperCase();

            const isFFLConsignment =
              normalize(consignment.shippingAddress.address1) ===
              normalize(dealer?.contact?.address?.street1) &&
              normalize(consignment.shippingAddress.postalCode) ===
              normalize(dealer?.contact?.address?.zip);

        // if the consignment is FFL and contains FFL and there's duplicate consignment
        //  (automatically created by the system) remove the duplicate consignment
        if (hasFFLItems && isFFLConsignment && hasDuplicateConsignments.length > 0) {
          for (const duplicateConsignment of checkout.consignments.filter((c: any) => c.id !== consignment.id)) {
            await SDK.removeConsignment(checkoutId, duplicateConsignment.id);
          }
          return window.location.reload();
        }

        // if the consignment is not FFL and contains FFL, remove the consignment and save the dealer
        if (hasFFLItems && !isFFLConsignment) {
          await SDK.removeConsignment(checkoutId, consignment.id);
          await SDK.saveDealer(checkoutId, dealer, undefined);
        }

        // if the consignment is FFL and the non-FFL item strategy is FORCE_TO_NON_FFL and the
        // consignment contains non-FFL items, remove the consignment and save the dealer
        // REMOVED. NEW ZIP GATE LOGIC RENDERS THIS REDUNDANT AND ALSO CAN RESULT IN INCORRECT PAGE RELOADS
        // if (isFFLConsignment && SDK.getConfig().nonFFLItemStrategy === "FORCE_TO_NON_FFL" && hasNonFFLItems) {
        //   await SDK.removeConsignment(checkoutId, consignment.id);
        //   await SDK.saveDealer(checkoutId, dealer);
        // }
      }
    } catch (error) {
      console.error(error);
    }
  }, [checkoutId]);

  const cartId = checkoutState.data.getCart()?.id;

  const handleInit = useCallback(async (zipOverride?: string) => {

    // EDIT RELOAD BUTTON
    const attachEditShippingHandler = () => {
      const button = document.querySelector(
        '.checkout-step--shipping [data-test="step-edit-button"]'
      ) as HTMLButtonElement | null;

      if (!button) return;

      // Prevent duplicate listeners
      if ((button as any).__fflBound) return;
      (button as any).__fflBound = true;

      button.addEventListener('click', async () => {
        const selectors = await checkoutService.loadCheckout(checkoutId, {
          params: { include: { "consignments.availableShippingOptions": true } },
        });

        const consignments = selectors.data.getConsignments?.() || [];

        for (const cons of consignments) {
          await checkoutService.deleteConsignment(cons.id);
        }

        setSelectedDealer(null);
        SDK.setSession(checkoutId, { postalCode: "", selectedDealer: "" });
        window.location.reload();
      });
    };

    const observer = new MutationObserver(() => {
      attachEditShippingHandler();
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });

    attachEditShippingHandler();
    // END EDIT RELOAD BUTTON

    const zipHasBeenChecked = zipOverride ?? lastCheckedZip;

    const checkout = await SDK.getCheckout();
    setCheckout(checkout);

    const { 
      isFFL, 
      isSuppressor, 
      isEntirelyFFL, 
      hasFederalFFLItems,
      fflLineItems,
      isStateRestrictedOnly, 
      restrictedTypesInCart, 
      potentialRestrictedProducts,
    } = await SDK.init();


    setIsFFL(isFFL);
    setFflLineItems(fflLineItems);
    setIsSuppressor(isSuppressor);
    setIsEntirelyFFL(isEntirelyFFL);
    setHasFederalFFLItems(Boolean(hasFederalFFLItems));
    setIsStateRestrictedOnly(isStateRestrictedOnly);
    setRestrictedTypesInCart(restrictedTypesInCart);
    setPotentialRestrictedProducts(potentialRestrictedProducts);

    const shouldLockShipping =
        !!(window as any).masterFFLCheckoutRestrictionResult?.hardBlocked ||
        (!hasFederalFFLItems && (potentialRestrictedProducts.size > 0) && !zipHasBeenChecked);

    setShippingLocked(shouldLockShipping);

    const allowIgnoreZipGate =
      sessionStorage.getItem('allowIgnoreZipGate') === 'true';

    if (!isFFL && !isSuppressor && !allowIgnoreZipGate) {
      handleCleanup();
    }

    if (isFFL) {
      (window as any).__masterFFLDetected = true;
    }

    return {
      isFFL,
      isSuppressor,
      isEntirelyFFL,
      hasFederalFFLItems,
      fflLineItems,
      isStateRestrictedOnly,
      restrictedTypesInCart,
      potentialRestrictedProducts,
    };
  }, [config.storeHash, cartId, handleCleanup, checkoutId, handleFixInvalidConsignments, lastCheckedZip]);

  useEffect(() => {
    if (!checkoutId || !storeHash || !cartId) return;
    if (hasInitializedRef.current) return;

    hasInitializedRef.current = true;

    (async () => {
      setInitReady(false);
      await handleInit();
      setInitReady(true);
    })();
  }, [checkoutId, storeHash, cartId, handleInit]);

  const contextValue = useMemo(
    () => ({
      checkoutService,
      checkoutState,
      config,
      initReady,
      isModalOpen,
      setIsModalOpen,
      values,
      setValues,
      handleSaveDealer,
      selectedDealer,
      setSelectedDealer,
      error,
      isFFL,
      isB2BFlowEnabled: isFFLB2BFlowEnabled,
      setIsFFL,
      isSuppressor,
      isEntirelyFFL,
      hasFederalFFLItems,
      isStateRestrictedOnly,
      restrictedTypesInCart,
      potentialRestrictedProducts,
      checkout,
      fflZip: lastCheckedZip,
      setLastCheckedZip,
      shippingLocked,
      setShippingLocked,
      handleCleanup,
      activeStepType,
      fflLineItems,
      activeStep,
      setSession: SDK.setSession,
      markFFLConsignment,
      stopConsignmentSideEffects,
      goToStep,
      setCheckout,
      fixInvalidConsignments: handleFixInvalidConsignments,
      runZipRestrictionCheck
    }),
    [
      checkoutService,
      checkoutState,
      config,
      initReady,
      isModalOpen,
      setIsModalOpen,
      values,
      setValues,
      handleSaveDealer,
      selectedDealer,
      setSelectedDealer,
      error,
      isFFL,
      isFFLB2BFlowEnabled,
      setLastCheckedZip,
      setIsFFL,
      isSuppressor,
      isEntirelyFFL,
      hasFederalFFLItems,
      isStateRestrictedOnly,
      restrictedTypesInCart,
      potentialRestrictedProducts,
      checkout,
      lastCheckedZip,
      shippingLocked,
      setShippingLocked,
      handleCleanup,
      activeStepType,
      fflLineItems,
      activeStep,
      markFFLConsignment,
      stopConsignmentSideEffects,
      goToStep,
      setCheckout,
      handleFixInvalidConsignments,
      runZipRestrictionCheck
    ]
  );

  useEffect(() => {

    console.groupCollapsed('[MasterFFLProvider] Context snapshot');
    console.log('activeStep:', activeStep?.type);
    console.log('checkoutId:', config?.checkoutId);
    console.log('storeHash:', config?.storeHash);

    console.log('initReady:', initReady);
    console.log('shippingLocked:', shippingLocked);
    console.log('lastCheckedZip:', lastCheckedZip);

    console.log('isFFL:', isFFL);
    console.log('FFL Line Items', fflLineItems);
    console.log('isSuppressor:', isSuppressor);
    console.log('isEntirelyFFL:', isEntirelyFFL);
    console.log('isStateRestrictedOnly:', isStateRestrictedOnly);
    console.log('restrictedTypesInCart:', restrictedTypesInCart);
    console.log('potentialRestrictedProducts', potentialRestrictedProducts);

    console.log('selectedDealer:', selectedDealer);
    console.log('values:', values);
    console.log('error:', error);

    // Cross-check your window-based state written by SDK.init()
    console.log('window.masterFFLState:', (window as any).masterFFLState);
    console.log('window.masterFFLConditional:', (window as any).masterFFLConditional);
    console.log('window.masterFFLPotential:', (window as any).masterFFLPotential);
    console.groupEnd();
  }, [
    activeStep?.type,
    config?.checkoutId,
    config?.storeHash,
    initReady,
    shippingLocked,
    lastCheckedZip,
      isFFL,
      isSuppressor,
      isEntirelyFFL,
      hasFederalFFLItems,
      isStateRestrictedOnly,
      restrictedTypesInCart,
      potentialRestrictedProducts,
    selectedDealer,
    values,
    error,
    getCheckoutStepStatuses,
  ]);


  return (
     <MasterFFLContext.Provider value={contextValue}>
        {children}
    </MasterFFLContext.Provider>
  );
};
