import type { CheckoutSelectors, CheckoutService } from "@bigcommerce/checkout-sdk";

export interface MasterFFLBaseConfig {
  env: "qa" | "production";
  storefrontApiToken: string;
  storeHash: string | undefined;
  checkoutId: string | undefined;
  nonFFLItemStrategy: "FORCE_TO_FFL" | "FORCE_TO_NON_FFL" | "ALLOW_CHOICE";
  hasMultiShippingEnabled: boolean;
  lang: {
    heading?: string;
    subheading?: string;
    buttonText?: string;
    postalCodeLabel?: string;
    termsLabel?: string;
    termsSelfFFLLabel?: string;
    selectedDealerLabel?: string;
  };
}

interface FFLDealerSelectorOptions {
  storeDomain: string;
  envMode: MasterFFLBaseConfig["env"];
  filters: "exclude_non_sot_dealer=true" | "" | undefined;
  headerColor?: string;
  buttonColor?: string;
  dealerSelectionCallback: (dealer: any) => Promise<void>;
}

interface FFLDealerSelector {
  configuration: { url: string };
  containerId: string;
  loadSubscriber: () => void;
  messageSubscriber: (message: string) => void;
  options: FFLDealerSelectorOptions;
  zipCode: string;
  show: () => void;
}

interface FFLDealerSelectorSDK {
  FFLDealerSelector: new (
    zipCode: string,
    selector: string,
    sdkOptions: { url: string },
    storeOptions: FFLDealerSelectorOptions
  ) => FFLDealerSelector;
}

declare global {
  interface Window {
    checkoutConfig: { checkoutId: string };
    masterFFLConfig?: MasterFFLBaseConfig;
    masterFFLCache: { [key: string]: any };
    FFLSelectSDK: { FFLDealerSelector: FFLDealerSelectorSDK["FFLDealerSelector"] };
  }
}

export interface MasterFFLConfig extends MasterFFLBaseConfig {
  baseUrl: string;
  appUrl: string;
  sdkUrl: string;
  storeDomain: string;
  storeHash: string | undefined;
  checkoutId: string | undefined;
}

export interface MasterFFLContextType {
  checkoutService: CheckoutService;
  checkoutState: CheckoutSelectors;
  isModalOpen: boolean;
  setIsModalOpen: (isModalOpen: boolean) => void;
  values: {
    postalCode: string;
    acceptTerms: boolean;
  };
  setValues: (values: { postalCode: string; acceptTerms: boolean }) => void;
  config: MasterFFLConfig;
  initReady: boolean;
  handleSaveDealer: (dealer: any) => Promise<void>;
  selectedDealer: any;
  setSelectedDealer: (selectedDealer: any) => void;
  error: string | null;
  isFFL: boolean;
  setIsFFL: (isFFL: any) => void;
  isB2BFlowEnabled: boolean;
  isSuppressor: boolean;
  isEntirelyFFL: boolean;
  hasFederalFFLItems?: boolean;
  isStateRestrictedOnly: boolean; 
  restrictedTypesInCart?: string[];
  potentialRestrictedProducts: any;
  activeStepType?: CheckoutStepType;
  shippingLocked: boolean; 
  setShippingLocked: (locked: boolean) => void;
  handleCleanup: () => void;
  checkout: any;
  fflZip?: string | null;
  setLastCheckedZip: (fflZip: any) => void;
  fflLineItems: Map<number, any>;
  markFFLConsignment: () => Promise<void>;
  stopConsignmentSideEffects: () => void;
  goToStep?: (step: any, options?: any) => void;
  setCheckout: (checkout: any) => void;
  setSession: (
    checkoutId: string | undefined,
    options: {
      postalCode?: string;
      acceptTerms?: string;
      selectedDealer: string;
    }
  ) => void;
  fixInvalidConsignments: (checkout: any) => Promise<void>;
  runZipRestrictionCheck: (zip: string, isDealerCallback?: boolean) => Promise<boolean>;
  mappingData?: {
    category_mapping: any[];
    ffl_custom_attribute_name: any;
    ffl_custom_attribute_value: any;
    ffl_firearm_custom_attribute_name: any;
    ffl_firearm_custom_attribute_value: any;
    rules?: any[];
    headerColor?: string;
    buttonColor?: string;
  } | null;
}

export interface withMasterFFLProps {
  masterFFL: MasterFFLContextType;
}

export interface CheckoutContextProps {
  checkoutService: CheckoutService;
  checkoutState: CheckoutSelectors;
}

export enum CheckoutStepType {
  Billing = "billing",
  Customer = "customer",
  Payment = "payment",
  Shipping = "shipping",
}
