import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { SDK } from "../../../sdk"; // adjust relative path to wherever SDK is from this file
import { useMasterFFL } from "../index"; // same file exports useMasterFFL in your current setup
import MasterFFLForm from "./MasterFFLForm";

export const MasterFFLShippingUI = () => {
    const { 
        shippingLocked, 
        isFFL, 
        isStateRestrictedOnly, 
        restrictedTypesInCart, 
        isSuppressor, 
        initReady,
        activeStepType,
        potentialRestrictedProducts,
        setShippingLocked,
        setIsFFL,
        markFFLConsignment,
        stopConsignmentSideEffects,
    } = useMasterFFL();

    useEffect(() => {

        const style = document.createElement("style");

        style.textContent = `
            .consignment-container a[data-test="reallocate-items-button"] {
              display: none !important;
            }
            [data-test="shipping-mode-toggle"] {
              display: none !important;
            }
            .consignment-container--ffl a[data-test="edit-shipping-address"], .consignment-container a[data-test="edit-shipping-address"] {
              display: none !important;
            }
            .consignment-container--ffl a[data-test="delete-consignment-button"] {
              display: none !important;
            }
            .optimizedCheckout-buttonPrimary {
              white-space: nowrap;
              flex-shrink: 0;
              min-width: max-content;
            }  
            .alertBox.alertBox--info + .add-consignment-button {
              display: none !important;
            }
            .consignment-container--ffl #addressToggle {
              display: none !important;
            }
            .alertBox + .consignment-container [data-test="enter-shipping-address"] {
              display: none !important;
            }
        `;

        document.head.appendChild(style);

        (() => {
          const update = () => {
            const containers = document.querySelectorAll('.consignment-container');
            containers.forEach((c, i) => {
              const btn = c.querySelector('[data-test="delete-consignment-button"]') as HTMLElement | null;
              if (!btn) return;

              btn.style.display =
                containers.length === 1 || i === 0 ? 'none' : '';
            });
          };

          update();
          new MutationObserver(update).observe(document.body, { childList: true, subtree: true });
        })();

    }, []);

    useEffect(() => {
      return () => {
        stopConsignmentSideEffects();
      };
    }, [stopConsignmentSideEffects]);

    useEffect(() => {
      const injectChangeZipButton = () => {
        const container = document.querySelector(
          '.form-legend-container.shipping-header'
        ) as HTMLElement | null;

        if (!container) return;

        const shouldShow =
          isFFL === false &&
          shippingLocked === false &&
          !!potentialRestrictedProducts &&
          potentialRestrictedProducts.size > 0;

        let btn = container.querySelector(
          '[data-masterffl-change-zip]'
        ) as HTMLButtonElement | null;

        if (!shouldShow) {
          if (btn) btn.style.display = 'none';
          return;
        }

        if (btn) {
          btn.style.display = 'inline';
          return;
        }

        const legend = container.querySelector(
          'legend[data-test="shipping-address-heading"]'
        );

        if (!legend) return;

        btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = 'Change Zip';
        btn.setAttribute('data-masterffl-change-zip', 'true');

        btn.style.marginLeft = '12px';
        btn.style.fontSize = '12px';
        btn.style.cursor = 'pointer';
        btn.style.background = 'none';
        btn.style.border = 'none';
        btn.style.color = '#4496f6';
        btn.style.textDecoration = 'underline';
        btn.style.display = 'inline';

        btn.addEventListener('click', () => {
          setShippingLocked(true);
          setIsFFL(false);
        });

        legend.insertAdjacentElement('afterend', btn);
      };

      injectChangeZipButton();

      const observer = new MutationObserver(injectChangeZipButton);
      observer.observe(document.body, { childList: true, subtree: true });

      return () => observer.disconnect();
    }, [shippingLocked, potentialRestrictedProducts, setShippingLocked, isFFL, setIsFFL]);


  // CONTEXT LOGGING
   useEffect(() => {
    console.groupCollapsed('[MasterFFLShippingUI] render snapshot');
    console.log('initReady:', initReady);
    console.log('shippingLocked:', shippingLocked);
    console.log('isFFL:', isFFL);
    console.log('isSuppressor:', isSuppressor);
    console.log('isStateRestrictedOnly:', isStateRestrictedOnly);
    console.log('restrictedTypesInCart:', restrictedTypesInCart);
    console.log('ACTIVE STEP', activeStepType);
    console.groupEnd();
  }, [shippingLocked, isFFL, isSuppressor, isStateRestrictedOnly, restrictedTypesInCart]);

  const allowIgnoreZipGateRef = React.useRef<boolean | null>(null);

  if (allowIgnoreZipGateRef.current === null && typeof window !== 'undefined') {
    allowIgnoreZipGateRef.current =
      sessionStorage.getItem('allowIgnoreZipGate') === 'true';
  }

  const allowIgnoreZipGate = allowIgnoreZipGateRef.current === true;

    useEffect(() => {
        if (allowIgnoreZipGate) {
          requestAnimationFrame(() => {
            sessionStorage.setItem('allowIgnoreZipGate', 'false');
          });
        }
      markFFLConsignment();
    }, []);

  return (
    <>
        {/* Safe to include these here as modal is portal-based anyway */}
        <MasterFFlScript />
        <MasterFFLModal />
        <MasterFFLHardBlockModal />

        {/* Only show gating/UI on the shipping step when appropriate */}
        {shippingLocked && !allowIgnoreZipGate && activeStepType === "shipping" && <MasterFFLZipGate />}

        {(isFFL || allowIgnoreZipGate) && (
            <>
                <MasterFFLForm />
            </>
        )}
    </>
  );
};

const MasterFFLHardBlockModal = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState("");
  const [title, setTitle] = useState("Shipping Restricted");
  const { setShippingLocked } = useMasterFFL();

  useEffect(() => {
    const onHardBlock = (event: Event) => {
      const customEvent = event as CustomEvent<any>;
      const nextTitle =
        typeof customEvent.detail?.title === "string" && customEvent.detail.title.trim()
          ? customEvent.detail.title.trim()
          : "Shipping Restricted";
      const nextMessage =
        typeof customEvent.detail?.message === "string" && customEvent.detail.message.trim()
          ? customEvent.detail.message.trim()
          : "Sorry, we cannot ship items in your cart to your state due to local regulations.";

      setTitle(nextTitle);
      setMessage(nextMessage);
      setIsOpen(true);
      setShippingLocked(true);
    };

    window.addEventListener("masterffl:hard-block", onHardBlock as EventListener);
    return () => {
      window.removeEventListener("masterffl:hard-block", onHardBlock as EventListener);
    };
  }, []);

  if (!isOpen) return null;

  return createPortal(
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(17, 24, 39, 0.45)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 1100,
        padding: 16,
      }}
      onClick={() => setIsOpen(false)}
    >
      <div
        className="form-body"
        style={{
          width: "100%",
          maxWidth: 520,
          borderRadius: 10,
          border: "1px solid #d9e2ec",
          background: "#fff",
          boxShadow: "0 10px 30px rgba(16, 24, 40, 0.18)",
          padding: 0,
          overflow: "hidden",
        }}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="masterffl-hard-block-title"
      >
        <div
          style={{
            padding: "14px 16px",
            borderBottom: "1px solid #e6edf3",
            background: "linear-gradient(180deg, #fff 0%, #f8fbff 100%)",
          }}
        >
          <h3 id="masterffl-hard-block-title" style={{ margin: 0, fontSize: 18, color: "#102a43" }}>
            {title}
          </h3>
        </div>
        <div style={{ padding: 16 }}>
          <p style={{ margin: 0, color: "#243b53", lineHeight: 1.45, fontWeight: 500 }}>
            {message}
          </p>
        </div>
        <div
          style={{
            padding: 16,
            borderTop: "1px solid #e6edf3",
            display: "flex",
            justifyContent: "flex-end",
          }}
        >
          <button
            type="button"
            className="button button--primary optimizedCheckout-buttonPrimary"
            onClick={() => setIsOpen(false)}
          >
            Close
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
};

const MasterFFLZipGate = () => {
  const { 
        shippingLocked, 
        config, 
        values, 
        setValues, 
        runZipRestrictionCheck,
        checkoutService
    } = useMasterFFL();

  const [error, setError] = useState<string | null>(null);
  const [isChecking, setIsChecking] = useState(false);

    
  if (!shippingLocked) return null;

  const handleZipSubmit = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();

    const zip = (values.postalCode || "").replace(/\D/g, "").slice(0, 5);

    if (zip.length !== 5) {
      setError("Enter a valid 5-digit ZIP code");
      return;
    }

    setError(null);
    setIsChecking(true);

    setValues({ ...values, postalCode: zip });
    sessionStorage.setItem(`${config.checkoutId}-postalCode`, zip);

    try {
        await runZipRestrictionCheck(zip);
        const restrictionResult = (window as any).masterFFLCheckoutRestrictionResult;
        if (restrictionResult?.hardBlocked) {
          return;
        }
        
        const selectors = await checkoutService.loadCheckout(config.checkoutId, {
          params: { include: { "consignments.availableShippingOptions": true } },
        });

        let consignments = selectors.data.getConsignments?.() || [];

        if (consignments.length >= 2) {
          consignments.forEach(cons => checkoutService.deleteConsignment(cons.id));
          sessionStorage.setItem('allowIgnoreZipGate', 'false');
          window.location.reload();
        }

    } finally {
      setIsChecking(false);
    }
  };

  return (
    <>
        <style
            dangerouslySetInnerHTML={{
            __html: `
                .checkout-form form { display: none !important; }
                #MasterFFL-form { display: none !important; }
            `,
            }}
        />
        <div
        className="form-body"
        style={{
            border: "1px solid #ebebeb",
            padding: "1.5rem",
            marginBottom: "15px",
            borderRadius: "4px",
        }}
        >
        {
          (() => {
            const conditional = (window as any).masterFFLConditional;
            const raw = typeof conditional?.uiText === "string" ? conditional.uiText : "";
            const chooseDealerButtonTextColor =
              typeof conditional?.chooseDealerButtonTextColor === "string"
                ? conditional.chooseDealerButtonTextColor.trim()
                : "";
            const chooseDealerButtonBgColor =
              typeof conditional?.chooseDealerButtonBgColor === "string"
                ? conditional.chooseDealerButtonBgColor.trim()
                : "";
            const zipGateButtonStyle = {
              ...(chooseDealerButtonTextColor ? { color: chooseDealerButtonTextColor } : {}),
              ...(chooseDealerButtonBgColor
                ? {
                    background: chooseDealerButtonBgColor,
                    backgroundColor: chooseDealerButtonBgColor,
                    borderColor: chooseDealerButtonBgColor,
                  }
                : {}),
            };
            let titleText = "";
            let descText = "";
            let btnText = "";

            try {
              const obj = JSON.parse(raw);
              titleText = typeof obj?.checkout_title === "string" ? obj.checkout_title.trim() : "";
              descText = typeof obj?.heading_text === "string" ? obj.heading_text.trim() : "";
              btnText = typeof obj?.button_text === "string" ? obj.button_text.trim() : "";
            } catch {
              titleText = "";
              descText = "";
              btnText = "";
            }

            return (
              <>
                <h3 style={{ fontSize: 18, marginBottom: 10 }}>
                  {titleText ? titleText : "Check shipping availability"}
                </h3>
                <p style={{ fontWeight: 600, marginBottom: 10 }}>
                  {descText ? descText : "Some items require ZIP verification before shipping options can be shown."}
                </p>
               
                <label className="form-label optimizedCheckout-form-label">
                    ZIP Code <span style={{ color: "red" }}>*</span>
                </label>
                <div style={{ display: "flex", gap: 10 }}>
                    <input
                    className="form-input optimizedCheckout-form-input"
                    style={{ paddingLeft: "25px", paddingRight: "25px" }}
                    value={values.postalCode}
                    onChange={(e) => {
                        setValues({ ...values, postalCode: e.target.value });
                        sessionStorage.setItem(`${config.checkoutId}-postalCode`, e.target.value);
                    }}
                    />

                    <button
                        className="button button--primary optimizedCheckout-buttonPrimary"
                        style={zipGateButtonStyle}
                        onClick={handleZipSubmit}
                        disabled={isChecking}
                        >
                        {btnText ? btnText : "Continue"}
                    </button>
                </div>
              </>
            )
          })()
        }
        {error && (
            <div className="form-field form-field--error">
            <label className="form-inlineMessage">{error}</label>
            </div>
        )}
        </div>
    </>
  );
};

const MasterFFlScript = () => {
  const { config } = useMasterFFL();

  useEffect(() => {
    const hasScript = document.querySelector(`script[src^="${config.sdkUrl}"]`);
    if (hasScript) return;

    const script = document.createElement("script");
    script.src = config.sdkUrl;
    document.body.appendChild(script);
  }, [config.sdkUrl]);

  return null;
};

function setFormControlValue(element: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement, value: string) {
  const tagName = element.tagName;

  if (tagName === "INPUT") {
    const input = element as HTMLInputElement;
    if (input.type === "checkbox" || input.type === "radio") {
      const checkedSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "checked")?.set;
      const boolValue = value === "true" || value === "on" || value === "1";
      checkedSetter ? checkedSetter.call(input, boolValue) : (input.checked = boolValue);
    } else {
      const valueSetter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
      valueSetter ? valueSetter.call(input, value) : (input.value = value);
    }
  } else if (tagName === "TEXTAREA") {
    const textarea = element as HTMLTextAreaElement;
    const valueSetter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;
    valueSetter ? valueSetter.call(textarea, value) : (textarea.value = value);
  } else if (tagName === "SELECT") {
    const select = element as HTMLSelectElement;
    const valueSetter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value")?.set;
    valueSetter ? valueSetter.call(select, value) : (select.value = value);
  }

  // Fire events so any React listeners update state
  element.dispatchEvent(new Event("input", { bubbles: true }));
  element.dispatchEvent(new Event("change", { bubbles: true }));
}

const MasterFFLModal = () => {
  const { 
    isModalOpen, 
    setIsModalOpen, 
    config, 
    values, 
    setValues, 
    setSelectedDealer, 
    isSuppressor, 
    setSession, 
    setShippingLocked,
    setLastCheckedZip
   // checkoutService, markFFLConsignment
  } = useMasterFFL();

  const SELECTOR_ID = "ffSelectFrame";

  const dealerSelectionCallback = async (selectedDealer: any) => {

    if (!selectedDealer) return;

        setShippingLocked(false);

        setValues({ ...values, postalCode: selectedDealer.address.zipCode });
        sessionStorage.setItem(`${config.checkoutId}-postalCode`, selectedDealer.address.zipCode);

        setSession(config.checkoutId,
        {
          postalCode: selectedDealer.address.zipCode,
          selectedDealer: JSON.stringify(selectedDealer),
        });

        setLastCheckedZip(selectedDealer.address.zipCode);

        const { shippingData, dealer } = await SDK.saveDealer(SDK.getConfig().checkoutId, selectedDealer, undefined);
        const address = shippingData?.address || {};
    
        // update the shipping address fields
        Object.keys(address).forEach((key) => {
          const input = document.querySelector(`[name="shippingAddress.${key}"]`) as HTMLInputElement | null;
          const addressLine1Input =
            key === "address1" ? (document.getElementById("addressLine1Input") as HTMLInputElement | null) : null;
          const nextValue = String(address[key as keyof typeof address] ?? "");

          if (input) {
            setFormControlValue(input, nextValue);
          }

          if (addressLine1Input) {
            setFormControlValue(addressLine1Input, nextValue);
          }
        });


        // FUTURE CODE OPTIMIZATION TO REPLACE ABOVE MANUAL DOM MANIPULATION...
        // const { dealer } = await SDK.saveDealer(SDK.getConfig().checkoutId, selectedDealer);

        // // Refresh checkout state so UI reflects the updated consignments/address.
        // // This avoids fighting controlled inputs like shippingAddress.postalCode.
        // await checkoutService.loadCheckout(config.checkoutId, {
        //   params: { include: { "consignments.availableShippingOptions": true } },
        // });

        // // Re-mark the FFL consignment after the DOM updates
        // setTimeout(() => {
        //   markFFLConsignment();
        // }, 0);
    
        setSelectedDealer(dealer);
        setIsModalOpen(false);

    };


  useEffect(() => {
    if (!isModalOpen) return;

    const t = setTimeout(async () => {
      const mappingData = await SDK.getMappingData();
      const selectorColors = {
        ...(mappingData?.headerColor ? { headerColor: mappingData.headerColor } : {}),
        ...(mappingData?.buttonColor ? { buttonColor: mappingData.buttonColor } : {}),
      };

      const fflSelect = new (window as any).FFLSelectSDK.FFLDealerSelector(
        values.postalCode,
        SELECTOR_ID,
        { url: config.baseUrl },
        {
          storeDomain: config.storeDomain,
          envMode: config.env,
          filters: isSuppressor ? "exclude_non_sot_dealer=true" : "",
          ...selectorColors,
          dealerSelectionCallback,
        }
      );

      fflSelect.show();
    }, 200);

    return () => clearTimeout(t);
  }, [
    isModalOpen,
    values.postalCode,
    config.baseUrl,
    config.storeDomain,
    config.env,
    isSuppressor,
  ]);

  if (!isModalOpen) return null;

  const modalContent = (
    <>
      <style
        dangerouslySetInnerHTML={{
          __html: `.ffl-modal-body { height: 100%; overflow: auto !important; padding: 0 !important; }`,
        }}
      />
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: "rgba(0, 0, 0, 0.5)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 1000,
        }}
        onClick={() => setIsModalOpen(false)}
      >
        <div
          style={{
            maxWidth: "95%",
            width: "100%",
            height: "80dvh",
            backgroundColor: "white",
            display: "flex",
            flexDirection: "column",
            position: "relative",
          }}
          onClick={(e) => e.stopPropagation()}
        >
          <div id={SELECTOR_ID} className="ffl-modal-body" style={{ height: "100%", flex: 1 }} />
        </div>
      </div>
    </>
  );

  return createPortal(modalContent, document.body);
};
