const fflProducts = new Map<number, boolean>();
const fflLineItems = new Map<number, any>();
let totalProductsInCart = 0;

const alwaysFFLProducts = new Map<number, boolean>();
const conditionalFFLProducts = new Map<number, boolean>();

const potentialRestrictedProducts = new Map<number, string>(); 
const potentialRestrictedTypes = new Set<string>();

type RuntimeRule = {
  id: number;
  name: string;
  description: string | null;
  type: string;
  priority: number;
  region_type: string;
  states: string[];
  run_transfer_workflow: boolean;
  is_active: boolean;
  products: number[];
  categories: number[];
  custom_fields: Array<{
    field_name: string;
    field_value?: string | null;
  }>;
  exclusion_products: number[];
  exclusion_categories: number[];
  exclusion_custom_fields: Array<{
    field_name: string;
    field_value?: string | null;
  }>;
  item_type: string | null;
  item_subtype: string | null;
};

