const normalizeText = (value: unknown) =>
  String(value ?? "").trim().toLowerCase();

const normalizeStateCode = (value: unknown) => {
  const normalized = String(value ?? "").trim().toUpperCase();
  return STATE_NAME_TO_CODE[normalized] || normalized;
};

const normalizeTypeLabel = (value: unknown) =>
  String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-");

const normalizeRules = (rules: unknown): RuntimeRule[] =>
  (Array.isArray(rules) ? rules : [])
    .map((rule: any) => ({
      id: Number(rule?.id),
      name: String(rule?.name || ""),
      description: rule?.description ? String(rule.description) : null,
      type: String(rule?.type || ""),
      priority: Number(rule?.priority || 0),
      region_type: String(rule?.region_type || "").toLowerCase(),
      states: Array.isArray(rule?.states)
        ? rule.states.map((state: unknown) => normalizeStateCode(state)).filter(Boolean)
        : [],
      run_transfer_workflow: Boolean(rule?.run_transfer_workflow),
      is_active: rule?.is_active !== false,
      products: Array.isArray(rule?.products)
        ? rule.products.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      categories: Array.isArray(rule?.categories)
        ? rule.categories.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      custom_fields: Array.isArray(rule?.custom_fields)
        ? rule.custom_fields
            .map((field: any) => ({
              field_name: String(field?.field_name || "").trim(),
              field_value:
                field?.field_value === null || field?.field_value === undefined
                  ? null
                  : String(field.field_value).trim(),
            }))
            .filter((field: any) => field.field_name)
        : [],
      exclusion_products: Array.isArray(rule?.exclusion_products)
        ? rule.exclusion_products.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      exclusion_categories: Array.isArray(rule?.exclusion_categories)
        ? rule.exclusion_categories.map((id: unknown) => Number(id)).filter((id: number) => Number.isInteger(id) && id > 0)
        : [],
      exclusion_custom_fields: Array.isArray(rule?.exclusion_custom_fields)
        ? rule.exclusion_custom_fields
            .map((field: any) => ({
              field_name: String(field?.field_name || "").trim(),
              field_value:
                field?.field_value === null || field?.field_value === undefined
                  ? null
                  : String(field.field_value).trim(),
            }))
            .filter((field: any) => field.field_name)
        : [],
      item_type:
        rule?.item_type === null || rule?.item_type === undefined
          ? null
          : String(rule.item_type).trim() || null,
      item_subtype:
        rule?.item_subtype === null || rule?.item_subtype === undefined
          ? null
          : String(rule.item_subtype).trim() || null,
    }))
    .filter((rule) => Number.isInteger(rule.id) && rule.id > 0 && rule.type && rule.is_active);

const ruleAppliesToRegion = (rule: RuntimeRule, stateCode?: string | null) => {
  if (rule.region_type === "federal") {
    return true;
  }

  if (!stateCode) {
    return false;
  }

  return rule.states.includes(normalizeStateCode(stateCode));
};

const productMatchesRuleCriteria = (
  product: any,
  criteria: Pick<RuntimeRule, "products" | "categories" | "custom_fields">
) => {
  const productId = Number(product?.entityId);
  const categoryIds = Array.isArray(product?.categoryIds)
    ? product.categoryIds.map((category: any) => Number(category?.entityId)).filter((id: number) => Number.isInteger(id))
    : [];
  const customFields = Array.isArray(product?.customFields) ? product.customFields : [];

  if (criteria.products.length && criteria.products.includes(productId)) {
    return true;
  }

  if (criteria.categories.length && criteria.categories.some((categoryId) => categoryIds.includes(categoryId))) {
    return true;
  }

  if (
    criteria.custom_fields.length &&
    criteria.custom_fields.some((ruleField) =>
      customFields.some((productField: any) => {
        const nameMatches = normalizeText(productField?.name) === normalizeText(ruleField.field_name);
        if (!nameMatches) {
          return false;
        }

        if (ruleField.field_value === null || ruleField.field_value === undefined || ruleField.field_value === "") {
          return true;
        }

        return normalizeText(productField?.value) === normalizeText(ruleField.field_value);
      })
    )
  ) {
    return true;
  }

  return false;
};

const ruleMatchesProduct = (rule: RuntimeRule, product: any) => {
  if (rule.type === "block_checkout") {
    return true;
  }

  const inclusionMatch = productMatchesRuleCriteria(product, {
    products: rule.products,
    categories: rule.categories,
    custom_fields: rule.custom_fields,
  });

  if (!inclusionMatch) {
    return false;
  }

  if (rule.type !== "route_to_ffl") {
    return true;
  }

  const exclusionMatch = productMatchesRuleCriteria(product, {
    products: rule.exclusion_products,
    categories: rule.exclusion_categories,
    custom_fields: rule.exclusion_custom_fields,
  });

  return !exclusionMatch;
};

const productMatchesApplicableExclusion = (
  product: any,
  rules: RuntimeRule[],
  stateCode?: string | null
) =>
  rules.some((rule) => {
    if (rule.type !== "route_to_ffl") {
      return false;
    }

    if (!ruleAppliesToRegion(rule, stateCode)) {
      return false;
    }

    return productMatchesRuleCriteria(product, {
      products: rule.exclusion_products,
      categories: rule.exclusion_categories,
      custom_fields: rule.exclusion_custom_fields,
    });
  });

const getWinningRule = (rules: RuntimeRule[]) => {
  if (!rules.length) {
    return null;
  }

  return rules.reduce((winner, current) => {
    if (!winner) {
      return current;
    }

    if (current.priority < winner.priority) {
      return current;
    }

    if (current.priority === winner.priority && current.id < winner.id) {
      return current;
    }

    return winner;
  }, null as RuntimeRule | null);
};

const getMostSpecificWinningRule = (rules: RuntimeRule[]) => {
  const stateSpecificRules = rules.filter((rule) => rule.region_type === "state");

  return getWinningRule(stateSpecificRules.length ? stateSpecificRules : rules);
};

const getRuleDisplayLabel = (rule: RuntimeRule) => {
  const trimmedName = String(rule?.name || "").trim();
  if (trimmedName) {
    return trimmedName;
  }

  if (rule.type === "route_to_ffl") return "Direct to Dealer";
  if (rule.type === "block_product_state") return "Restricted Product";
  if (rule.type === "block_checkout") return "State Block";

  return "Restricted Item";
};

const getRuleDescription = (rule: RuntimeRule | null) =>
  rule && typeof rule.description === "string" ? rule.description : "";

const getProductCustomField = (product: any, fieldName: unknown) => {
  const normalizedFieldName = normalizeText(fieldName);

  if (!normalizedFieldName || !Array.isArray(product?.customFields)) {
    return null;
  }

  return (
    product.customFields.find(
      (field: any) => normalizeText(field?.name) === normalizedFieldName
    ) || null
  );
};

const hasLegacyCategoryMappingMatch = (
  product: any,
  mapping: MasterFFLContextType["mappingData"]
) => {
  const categoryIds = Array.isArray(product?.categoryIds)
    ? product.categoryIds
        .map((category: any) => Number(category?.entityId))
        .filter((id: number) => Number.isInteger(id) && id > 0)
    : [];

  const categoryMappings = Array.isArray(mapping?.category_mapping)
    ? mapping.category_mapping
    : [];

  return categoryMappings.some((entry: any) =>
    categoryIds.includes(Number(entry?.categoryId))
  );
};

const isLegacyFflProduct = (
  product: any,
  mapping: MasterFFLContextType["mappingData"]
) => {
  const fflField = getProductCustomField(
    product,
    mapping?.ffl_custom_attribute_name
  );

  if (fflField) {
    return normalizeText(fflField?.value) !== "no";
  }

  return hasLegacyCategoryMappingMatch(product, mapping);
};

const isLegacyNfaProduct = (product: any, mapping: MasterFFLContextType["mappingData"]) => {
  const fflFirearmAttr =
    mapping?.ffl_firearm_custom_attribute_name?.trim()?.toLowerCase() ?? "";
  const fflFirearmValue = mapping?.ffl_firearm_custom_attribute_value ?? "";

  return Array.isArray(product?.customFields) && product.customFields.some(
    (field: any) =>
      normalizeText(field?.name) === fflFirearmAttr &&
      normalizeText(field?.value) === normalizeText(fflFirearmValue?.[3])
  );
};


const init = async () => {
  const [mapping, cart, checkoutSettings] = await Promise.all([
    getMappingData(),
    getCart(),
    getCheckoutSettings(),
  ]);

  let isFFL = false;
  let isSuppressor = false;
  let isEntirelyFFL = false;

  window.masterFFLConfig = window.masterFFLConfig || ({} as MasterFFLBaseConfig);
  window.masterFFLConfig.hasMultiShippingEnabled =
    checkoutSettings.storeConfig.checkoutSettings.hasMultiShippingEnabled;

  fflProducts.clear();
  fflLineItems.clear();
  alwaysFFLProducts.clear();
  conditionalFFLProducts.clear();
  potentialRestrictedProducts.clear();
  potentialRestrictedTypes.clear();

  const conditional = (window as any).masterFFLConditional;
  const currentState = conditional?.state ? normalizeStateCode(conditional.state) : null;
  const rules = normalizeRules((mapping as any)?.rules);

  console.log("[MasterFFL][Rules] state debug", {
    raw: conditional?.state ?? null,
    normalized: normalizeStateCode(conditional?.state),
  });

  console.log("[MasterFFL][Rules] init context", {
    storeHash: getConfig().storeHash || null,
    currentState,
    totalRulesReceived: Array.isArray((mapping as any)?.rules) ? (mapping as any).rules.length : 0,
    activeRulesNormalized: rules.map((rule) => ({
      id: rule.id,
      name: rule.name,
      type: rule.type,
      priority: rule.priority,
      region_type: rule.region_type,
      states: rule.states,
      products: rule.products,
      categories: rule.categories,
      custom_fields: rule.custom_fields,
    })),
  });

  const productIds = cart?.lineItems.physicalItems.map(
    (item: any) => item.productEntityId
  ) || [];
  const products = await SDK.getProducts(productIds);
  totalProductsInCart = products.length;
  const derivedRestrictedTypes = new Set<string>();
  const blockedProductIds = new Set<number>();
  let matchedBlockAllRule: RuntimeRule | null = null;
  let matchedBlockedProductRule: RuntimeRule | null = null;

  products.forEach((product: any) => {
    const applicableExclusionMatch = productMatchesApplicableExclusion(product, rules, currentState);

    if (applicableExclusionMatch) {
      return;
    }

    const legacyFflMatch = isLegacyFflProduct(product, mapping);

    if (legacyFflMatch) {
      fflProducts.set(product.entityId, true);
      alwaysFFLProducts.set(product.entityId, true);
    }

    if (isLegacyNfaProduct(product, mapping)) {
      isSuppressor = true;
    }

    console.log("RULES: ", rules);
    const allMatchingRules = rules.filter(
      (rule) => rule.type !== "block_checkout" && ruleMatchesProduct(rule, product)
    );

    console.log("ALL MATCHING RULES", allMatchingRules);

    const stateDependentMatchingRules = allMatchingRules.filter(
      (rule) => rule.region_type === "state"
    );

    if (stateDependentMatchingRules.length > 0) {
      const potentialRule = getWinningRule(stateDependentMatchingRules);
      if (potentialRule) {
        const label = getRuleDisplayLabel(potentialRule);
        potentialRestrictedProducts.set(product.entityId, label);
        potentialRestrictedTypes.add(label);
      }
    }

    const activeRulesForState = allMatchingRules.filter((rule) =>
      ruleAppliesToRegion(rule, currentState)
    );

    const winningRule = getMostSpecificWinningRule(activeRulesForState);
    console.log("[MasterFFL][Rules] product evaluation", {
      productId: product.entityId,
      categoryIds: Array.isArray(product?.categoryIds)
        ? product.categoryIds.map((category: any) => category?.entityId)
        : [],
      customFields: Array.isArray(product?.customFields)
        ? product.customFields.map((field: any) => ({
            name: field?.name,
            value: field?.value,
          }))
        : [],
      currentState,
      matchedRuleIds: allMatchingRules.map((rule) => rule.id),
      activeRuleIdsForState: activeRulesForState.map((rule) => rule.id),
      winningRule: winningRule
        ? {
            id: winningRule.id,
            name: winningRule.name,
            type: winningRule.type,
            priority: winningRule.priority,
            states: winningRule.states,
          }
        : null,
    });

    if (!winningRule) {
      return;
    }

    const label = getRuleDisplayLabel(winningRule);
    derivedRestrictedTypes.add(label);

    if (winningRule.type === "route_to_ffl") {
      fflProducts.set(product.entityId, true);

      if (winningRule.region_type === "federal") {
        alwaysFFLProducts.set(product.entityId, true);
      } else {
        conditionalFFLProducts.set(product.entityId, true);
      }

      if (
        normalizeTypeLabel(winningRule.item_type) === "nfa" ||
        isLegacyNfaProduct(product, mapping)
      ) {
        isSuppressor = true;
      }
    }

    if (winningRule.type === "block_product_state") {
      blockedProductIds.add(Number(product.entityId));

      if (
        !matchedBlockedProductRule ||
        winningRule.priority < matchedBlockedProductRule.priority ||
        (winningRule.priority === matchedBlockedProductRule.priority &&
          winningRule.id < matchedBlockedProductRule.id)
      ) {
        matchedBlockedProductRule = winningRule;
      }
    }
  });

  if (currentState) {
    matchedBlockAllRule = getWinningRule(
      rules.filter((rule) => rule.type === "block_checkout" && ruleAppliesToRegion(rule, currentState))
    );
  }

  console.log("[MasterFFL][Rules] block checkout evaluation", {
    currentState,
    blockCheckoutRuleIdsForState: rules
      .filter((rule) => rule.type === "block_checkout" && ruleAppliesToRegion(rule, currentState))
      .map((rule) => ({
        id: rule.id,
        name: rule.name,
        priority: rule.priority,
        states: rule.states,
      })),
    matchedBlockAllRule: matchedBlockAllRule
      ? {
          id: matchedBlockAllRule.id,
          name: matchedBlockAllRule.name,
          priority: matchedBlockAllRule.priority,
          states: matchedBlockAllRule.states,
          description: matchedBlockAllRule.description,
        }
      : null,
    blockedProductIds: [...blockedProductIds],
  });

  (window as any).masterFFLPotential = {
    hasPotentialRestrictions: potentialRestrictedProducts.size > 0,
    types: [...potentialRestrictedTypes],
  };

  /*
   * ---------------------------------------------------------
   * 4️. Map cart line items → FFL line items
   * ---------------------------------------------------------
   */
  cart?.lineItems.physicalItems.forEach((item: any) => {
    if (fflProducts.get(item.productEntityId)) {
      fflLineItems.set(item.entityId, item);
    }
  });

  /*
   * ---------------------------------------------------------
   * 5️. Final flags
   * ---------------------------------------------------------
   */
  
  const hasGlobalBlock = Boolean(matchedBlockAllRule);

  console.log("HASGLOBALBLOCK: ", hasGlobalBlock);

  isFFL = fflLineItems.size > 0 || hasGlobalBlock;
  
  isEntirelyFFL =
    products.length > 0 && products.length === fflProducts.size;

  const hasAlwaysFFL = alwaysFFLProducts.size > 0;
  const hasConditionalFFL = conditionalFFLProducts.size > 0;
  const isStateRestrictedOnly = hasConditionalFFL && !hasAlwaysFFL && !isSuppressor;
  const hardBlockMessage = getRuleDescription(matchedBlockAllRule) || getRuleDescription(matchedBlockedProductRule);

  const fflState = {
    isFFL,
    fflLineItems,
    isSuppressor,
    isEntirelyFFL,
    hasFederalFFLItems: hasAlwaysFFL,
    isStateRestrictedOnly,
    potentialRestrictedProducts,
    conditionalFFLProducts,
    potentialRestrictedTypes: [...potentialRestrictedTypes],
    restrictedTypesInCart: [...derivedRestrictedTypes],
  };

  (window as any).masterFFLRuleEvaluation = {
    state: currentState,
    matchedBlockAllRuleId: matchedBlockAllRule?.id || null,
    hardBlocked: Boolean(matchedBlockAllRule) || blockedProductIds.size > 0,
    blockedProductIds: [...blockedProductIds],
    hardBlockMessage,
    directToDealerRequired: isFFL,
    directToDealerRestrictedKeys: [...derivedRestrictedTypes],
  };

  (window as any).masterFFLState = fflState;

  return fflState;
};

